const orders = [
  { item: 'pen', qty: 3, price: 1.5 },
  { item: 'book', qty: 1, price: 12 },
  { item: 'pencil', qty: 5, price: 0.5 },
];

const total = orders
  .filter(o => o.qty > 1)
  .map(o => o.qty * o.price)
  .reduce((sum, subtotal) => sum + subtotal, 0);

console.log(total);

const totalDirect = orders.reduce((sum, o) => sum + o.qty * o.price, 0);
console.log(totalDirect);
